#!/usr/bin/env node
// SPDX-License-Identifier: MIT

// Minimal dependency-free static HTTPS server for local adapter repository
// testing. Serves the published `public/` directory with the certificate
// generated by mkcert.

import { createReadStream, readFileSync, statSync } from 'node:fs';
import { createServer } from 'node:https';
import { extname, resolve, sep } from 'node:path';

const [rootArgument, portArgument, certPath, keyPath] = process.argv.slice(2);

if (!rootArgument || !portArgument || !certPath || !keyPath) {
  console.error(
    'Usage: serve-https.mjs <directory> <port> <cert.pem> <key.pem>',
  );
  process.exit(1);
}

const root = resolve(rootArgument);
const port = Number(portArgument);

if (!Number.isInteger(port) || port < 1 || port > 65535) {
  console.error(`Invalid port: ${portArgument}`);
  process.exit(1);
}

const contentTypes = new Map([
  ['.json', 'application/json; charset=utf-8'],
  ['.js', 'text/javascript; charset=utf-8'],
  ['.sig', 'text/plain; charset=utf-8'],
  ['.html', 'text/html; charset=utf-8'],
  ['.css', 'text/css; charset=utf-8'],
  ['.map', 'application/json; charset=utf-8'],
]);

function isInsideRoot(path) {
  return path === root || path.startsWith(`${root}${sep}`);
}

const server = createServer(
  {
    cert: readFileSync(certPath),
    key: readFileSync(keyPath),
  },
  (request, response) => {
    const host = request.headers.host ?? `localhost:${port}`;
    const requestURL = new URL(request.url ?? '/', `https://${host}`);
    const pathname = decodeURIComponent(requestURL.pathname);
    const candidate = resolve(root, `.${pathname}`);

    if (!isInsideRoot(candidate)) {
      response.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Forbidden');
      return;
    }

    try {
      const filePath = statSync(candidate).isDirectory()
        ? resolve(candidate, 'index.html')
        : candidate;
      const size = statSync(filePath).size;

      response.writeHead(200, {
        'Content-Type':
          contentTypes.get(extname(filePath).toLowerCase()) ??
          'application/octet-stream',
        'Content-Length': size,
        'Cache-Control': 'no-store',
      });
      createReadStream(filePath).pipe(response);
    } catch {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end('Not found');
    }
  },
);

server.listen(port, '0.0.0.0', () => {
  console.log(`Serving ${root}`);
  console.log(`Index URL: https://localhost:${port}/index.json`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => process.exit(0));
  });
}
